// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount) public {
        vm.assume(user != address(0));
        vm.assume(depositAmount > 0 && depositAmount < address(this).balance / 2);
        uint256 initialUserBalance = user.balance;
        uint256 initialContractBalance = address(c).balance;

        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Now withdraw all
        vm.prank(user);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint256 finalUserBalance = user.balance;
        // If withdrawal succeeded, the user should have at least the deposit amount back (minus gas, but Ether is conserved)
        // If it failed (mutant), the user's balance didn't increase, so final balance < initial + deposit
        assertTrue(!success || finalUserBalance >= initialUserBalance + depositAmount);
    }
}

